text:
Two likely bugs:

**Bug 1 — Units mismatch (most common)**

JWT `exp` = **seconds** since epoch. `Date.now()` = **milliseconds**. Direct compare always wrong.

```js
// BAD — exp (e.g. 1700000000) always < Date.now() (e.g. 1700000000000)
if (decoded.exp < Date.now()) { /* always fires */ }

// GOOD
if (decoded.exp < Date.now() / 1000) { /* correct */ }
// or
if (decoded.exp * 1000 < Date.now()) { /* correct */ }
```

**Bug 2 — Inverted logic**

```js
// BAD — calls next() when expired
if (decoded.exp < Date.now() / 1000) {
  next(); // ← wrong branch
}

// GOOD
if (decoded.exp < Date.now() / 1000) {
  return res.status(401).json({ error: 'Token expired' });
}
next();
```

**Clean version:**

```js
function authMiddleware(req, res, next) {
  const token = req.headers.authorization?.split(' ')[1];
  if (!token) return res.status(401).json({ error: 'No token' });

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    // jwt.verify() throws if expired — handles this for you
    req.user = decoded;
    next();
  } catch (err) {
    const msg = err.name === 'TokenExpiredError' ? 'Token expired' : 'Invalid token';
    return res.status(401).json({ error: msg });
  }
}
```

Use `jwt.verify()` — throws `TokenExpiredError` automatically. Manual `exp` check = redundant + error-prone.
